-- Cinq messaging channel: the retention job, every 15 minutes, inside the database (needs pg_cron; on Supabase, enable Cron under Integrations first)
-- Generated by `npm run messages:sql` from src/lib/channel/postgres-store.ts. Edit the code, not this file.
create extension if not exists pg_cron;
select cron.schedule('cinq-messages-sweep', '*/15 * * * *', $job$select channel_sweep(extract(epoch from now()) * 1000, 86400000, 604800000, 604800000)$job$);
